import java.util.*;

public class Main {
    public static void main(String[] args) {
        BookingService bookingService = new BookingService();
        bookingService.createListing("listing-1");
        bookingService.createListing("listing-2");

        // A guest books listing-1 for days 10 to 15.
        System.out.println("Book listing-1 [10,15): " + bookingService.tryReserve("listing-1", 10, 15).status);

        // A conflicting booking attempt on the same listing: [12,18) overlaps [10,15).
        System.out.println("Book listing-1 [12,18), should conflict: " + bookingService.tryReserve("listing-1", 12, 18).status);

        // A booking that fits exactly in the gap right after the first: [15,20).
        System.out.println("Book listing-1 [15,20), should succeed: " + bookingService.tryReserve("listing-1", 15, 20).status);

        // A completely unrelated listing books its own, independent dates with no interference at all.
        System.out.println("Book listing-2 [10,15), independent of listing-1: " + bookingService.tryReserve("listing-2", 10, 15).status);

        // Simulate a genuinely concurrent competing booking landing between this attempt's read and its own commit.
        bookingService.debugInjectConcurrentBookingOnce("listing-1", 25, 30);
        BookingResult raceResult = bookingService.tryReserve("listing-1", 20, 24);
        System.out.println("Book listing-1 [20,24) with a simulated concurrent race: " + raceResult.status + ", attempts=" + raceResult.attemptsUsed);

        System.out.println("listing-1's final reservations: " + bookingService.reservationsFor("listing-1"));
        System.out.println("listing-2's final reservations: " + bookingService.reservationsFor("listing-2"));
    }
}

// The outcome of a booking attempt, including how many compare-and-swap
// attempts it took, to make the retry-under-contention behavior visible.
class BookingResult {
    String status;
    int attemptsUsed;

    BookingResult(String status, int attemptsUsed) {
        this.status = status;
        this.attemptsUsed = attemptsUsed;
    }
}

// One listing's durable state: its reservations, sorted by start day, and a
// version number used for optimistic concurrency control.
class Listing {
    TreeMap<Integer, int[]> reservationsByStart = new TreeMap<>(); // startDay -> [startDay, endDay]
    int version = 0;
}

// Manages listings with optimistic concurrency control: a booking attempt
// reads the current version, checks for a date overlap, and commits only if
// the version is still unchanged, retrying against fresh state otherwise.
class BookingService {
    private final Map<String, Listing> listings = new HashMap<>();
    private String pendingRaceListingId = null; // one-shot hook, armed by debugInjectConcurrentBookingOnce
    private int pendingRaceStart, pendingRaceEnd;

    void createListing(String listingId) {
        listings.put(listingId, new Listing());
    }

    // Arms a one-time simulated concurrent booking, purely to deterministically
    // demonstrate the compare-and-swap retry path in this single-threaded demo.
    void debugInjectConcurrentBookingOnce(String listingId, int startDay, int endDay) {
        this.pendingRaceListingId = listingId;
        this.pendingRaceStart = startDay;
        this.pendingRaceEnd = endDay;
    }

    BookingResult tryReserve(String listingId, int startDay, int endDay) {
        int attempts = 0;
        while (true) {
            attempts++;
            Listing listing = listings.get(listingId);
            int seenVersion = listing.version;

            if (hasConflict(listing, startDay, endDay)) {
                return new BookingResult("DENIED_DATES_UNAVAILABLE", attempts);
            }

            // Deterministically simulate a concurrent booking landing between this
            // read and this attempt's own commit, exactly once, if armed for this listing.
            if (listingId.equals(pendingRaceListingId)) {
                listing.reservationsByStart.put(pendingRaceStart, new int[]{pendingRaceStart, pendingRaceEnd});
                listing.version += 1;
                pendingRaceListingId = null; // fire only once
            }

            boolean committed = compareAndSwapReserve(listingId, seenVersion, startDay, endDay);
            if (committed) {
                return new BookingResult("CONFIRMED", attempts);
            }
            // Version mismatch: someone else committed first. Loop and retry with fresh state.
        }
    }

    private boolean hasConflict(Listing listing, int startDay, int endDay) {
        Map.Entry<Integer, int[]> before = listing.reservationsByStart.floorEntry(startDay);
        if (before != null && before.getValue()[1] > startDay) return true; // preceding reservation ends after this starts
        Map.Entry<Integer, int[]> after = listing.reservationsByStart.ceilingEntry(startDay);
        if (after != null && after.getKey() < endDay) return true; // following reservation starts before this ends
        return false;
    }

    private boolean compareAndSwapReserve(String listingId, int expectedVersion, int startDay, int endDay) {
        Listing listing = listings.get(listingId);
        if (listing.version != expectedVersion) {
            return false; // the version changed since this attempt's read; reject, caller will retry
        }
        listing.reservationsByStart.put(startDay, new int[]{startDay, endDay});
        listing.version++;
        return true;
    }

    List<String> reservationsFor(String listingId) {
        List<String> result = new ArrayList<>();
        for (int[] r : listings.get(listingId).reservationsByStart.values()) {
            result.add(r[0] + "-" + r[1]);
        }
        return result;
    }
}

