// The outcome of a booking attempt, including how many compare-and-swap
// attempts it took, to make the retry-under-contention behavior visible.
struct BookingResult {
    string status;
    int attemptsUsed;
};

// One listing's durable state: its reservations, sorted by start day, and a
// version number used for optimistic concurrency control.
struct Listing {
    map<int, pair<int, int>> reservationsByStart; // startDay -> (startDay, endDay)
    int version = 0;
};

// Manages listings with optimistic concurrency control: a booking attempt
// reads the current version, checks for a date overlap, and commits only if
// the version is still unchanged, retrying against fresh state otherwise.
class BookingService {
public:
    void createListing(const string& listingId) {
        listings[listingId] = Listing();
    }

    void debugInjectConcurrentBookingOnce(const string& listingId, int startDay, int endDay) {
        pendingRaceListingId = listingId;
        pendingRaceStart = startDay;
        pendingRaceEnd = endDay;
    }

    BookingResult tryReserve(const string& listingId, int startDay, int endDay) {
        int attempts = 0;
        while (true) {
            attempts++;
            Listing& listing = listings[listingId];
            int seenVersion = listing.version;

            if (hasConflict(listing, startDay, endDay)) {
                return {"DENIED_DATES_UNAVAILABLE", attempts};
            }

            // Deterministically simulate a concurrent booking landing between this
            // read and this attempt's own commit, exactly once, if armed for this listing.
            if (listingId == pendingRaceListingId) {
                listing.reservationsByStart[pendingRaceStart] = {pendingRaceStart, pendingRaceEnd};
                listing.version += 1;
                pendingRaceListingId = ""; // fire only once
            }

            if (compareAndSwapReserve(listingId, seenVersion, startDay, endDay)) {
                return {"CONFIRMED", attempts};
            }
            // Version mismatch: someone else committed first. Loop and retry with fresh state.
        }
    }

    vector<string> reservationsFor(const string& listingId) {
        vector<string> result;
        for (const auto& entry : listings[listingId].reservationsByStart) {
            result.push_back(to_string(entry.second.first) + "-" + to_string(entry.second.second));
        }
        return result;
    }

private:
    map<string, Listing> listings;
    string pendingRaceListingId = "";
    int pendingRaceStart = 0, pendingRaceEnd = 0;

    bool hasConflict(const Listing& listing, int startDay, int endDay) {
        auto before = listing.reservationsByStart.upper_bound(startDay);
        if (before != listing.reservationsByStart.begin()) {
            --before;
            if (before->second.second > startDay) return true; // preceding reservation ends after this starts
        }
        auto after = listing.reservationsByStart.lower_bound(startDay);
        if (after != listing.reservationsByStart.end() && after->first < endDay) return true; // following reservation starts before this ends
        return false;
    }

    bool compareAndSwapReserve(const string& listingId, int expectedVersion, int startDay, int endDay) {
        Listing& listing = listings[listingId];
        if (listing.version != expectedVersion) {
            return false; // the version changed since this attempt's read; reject, caller will retry
        }
        listing.reservationsByStart[startDay] = {startDay, endDay};
        listing.version++;
        return true;
    }
};

int main() {
    BookingService bookingService;
    bookingService.createListing("listing-1");
    bookingService.createListing("listing-2");

    cout << "Book listing-1 [10,15): " << bookingService.tryReserve("listing-1", 10, 15).status << endl;
    cout << "Book listing-1 [12,18), should conflict: " << bookingService.tryReserve("listing-1", 12, 18).status << endl;
    cout << "Book listing-1 [15,20), should succeed: " << bookingService.tryReserve("listing-1", 15, 20).status << endl;
    cout << "Book listing-2 [10,15), independent of listing-1: " << bookingService.tryReserve("listing-2", 10, 15).status << endl;

    bookingService.debugInjectConcurrentBookingOnce("listing-1", 25, 30);
    BookingResult raceResult = bookingService.tryReserve("listing-1", 20, 24);
    cout << "Book listing-1 [20,24) with a simulated concurrent race: " << raceResult.status << ", attempts=" << raceResult.attemptsUsed << endl;

    cout << "listing-1's final reservations: ";
    for (const auto& r : bookingService.reservationsFor("listing-1")) cout << r << " ";
    cout << endl;

    cout << "listing-2's final reservations: ";
    for (const auto& r : bookingService.reservationsFor("listing-2")) cout << r << " ";
    cout << endl;

    return 0;
}

